// BUG: Array.prototype.unshift() prepends by shifting every existing
// element one slot to the right - O(n) per call, so calling it once per
// input item is O(n^2) total.
export function prependAll(items: number[]): number[] {
  const result: number[] = [];
  for (const item of items) {
    result.unshift(item);
  }
  return result;
}

