function assertEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(`${message}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
  }
}

import { prependAll } from "./prepend";

// basic correctness: each item is prepended, so the result is the reverse
// of the input order
assertEqual(prependAll([1, 2, 3]), [3, 2, 1], "basic reverse order");

// empty input
assertEqual(prependAll([]), [], "empty input");

// single item
assertEqual(prependAll([7]), [7], "single item");

// performance
{
  const n = 300000;
  const items = Array.from({ length: n }, (_, i) => i);
  const expected = [...items].reverse();

  const start = Date.now();
  const got = prependAll(items);
  const elapsed = (Date.now() - start) / 1000;

  assertEqual(got[0], expected[0], "large-input first element");
  assertEqual(got[n - 1], expected[n - 1], "large-input last element");
  assertEqual(got.length, n, "large-input length");
  // calibrated: unshift() per item is ~2.4s on fast native hardware at
  // n=300000; push+reverse is ~0.01s
  if (elapsed >= 1.2) {
    throw new Error(
      `prependAll took ${elapsed.toFixed(2)}s for ${n} items; expected push() + a single ` +
        `reverse() at the end, not unshift() per item (O(n^2))`,
    );
  }
}

