reference_solution.prepend.ts:
// push() is amortized O(1); reversing the fully-built array once at the
// end is O(n) - O(n) total instead of O(n^2).
export function prependAll(items: number[]): number[] {
  const result: number[] = [];
  for (const item of items) {
    result.push(item);
  }
  result.reverse();
  return result;
}

